// THE INSTANCE THE CHAIN ACTUALLY RESOLVES.
//
// Identical in name, version and export name to the top-level install one
// directory up. The only thing that distinguishes them is where they sit
// on disk -- which is precisely what decides which one runs.
function dangerousOp(input) {
  return reachedSinkNested(input);
}

function reachedSinkNested(input) {
  return "nested-instance:" + input;
}

exports.dangerousOp = dangerousOp;
